cd /workspace && node -e "
const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/order_summary.xlsx');
console.log('Sheet names:', wb.SheetNames);

for (const name of wb.SheetNames) {
  const ws = wb.Sheets[name];
  const data = XLSX.utils.sheet_to_json(ws);
  const range = XLSX.utils.decode_range(ws['!ref'] || 'A1');
  console.log(\"\n=== Sheet: \" + name + \" ===\");
  console.log('Rows:', data.length, '| Columns:', range.e.c - range.s.c + 1);

  // Print headers
  const headers = Object.keys(data[0] || {});
  console.log('Headers:', headers);

  // Print all rows (or first 50 if large)
  const rows = data.slice(0, 50);
  console.log('\nData:');
  console.table(rows);

  // Summary stats for numeric columns
  console.log('\n--- Summary Statistics ---');
  for (const h of headers) {
    const vals = data.map(r => r[h]).filter(v => typeof v === 'number');
    if (vals.length > 0) {
      const sum = vals.reduce((a, b) => a + b, 0);
      const min = Math.min(...vals);
      const max = Math.max(...vals);
      const avg = sum / vals.length;
      console.log(h + ': count=' + vals.length + ', sum=' + sum.toFixed(2) + ', min=' + min + ', max=' + max + ', avg=' + avg.toFixed(2));
    }
  }

  // Count unique values for string columns
  console.log('\n--- Categorical Columns ---');
  for (const h of headers) {
    const vals = data.map(r => r[h]).filter(v => typeof v === 'string');
    if (vals.length > 0) {
      const unique = [...new Set(vals)];
      console.log(h + ': ' + unique.length + ' unique values → ' + unique.slice(0, 15).join(', ') + (unique.length > 15 ? '...' : ''));
    }
  }
}
"
